"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["7628"],{6075(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>c,toc:()=>l,assets:()=>d});var s=JSON.parse('{"id":"m8-config-rbac-microservices/lesson-1-config-access-control","title":"Lesson 1: Configuration & Access Control","description":"By now Fernwood Goods runs fully on the cluster. A frontend Deployment, a backend Deployment, a","source":"@site/docs/m8-config-rbac-microservices/lesson-1-config-access-control.md","sourceDirName":"m8-config-rbac-microservices","slug":"/m8-config-rbac-microservices/lesson-1-config-access-control","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-1-config-access-control","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson 1: Configuration & Access Control"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/k8s-distributed-systems/docs/m7-envoy-ingress/deep-dive"},"next":{"title":"Lesson 2: The Microservices Outlook","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-2-microservices-outlook"}}'),o=t(4848),i=t(8453),a=t(7684);let r={sidebar_position:1,title:"Lesson 1: Configuration & Access Control"},c="Configuration & Access Control",d={},l=[{value:"The analogy: a secured research campus",id:"the-analogy-a-secured-research-campus",level:2},{value:"Moving configuration out: ConfigMaps and Secrets",id:"moving-configuration-out-configmaps-and-secrets",level:2},{value:"Three gates: authentication, authorization, admission control",id:"three-gates-authentication-authorization-admission-control",level:2},{value:"Service Accounts: identity for Pods",id:"service-accounts-identity-for-pods",level:2},{value:"RBAC: Roles, ClusterRoles, and bindings",id:"rbac-roles-clusterroles-and-bindings",level:2},{value:"NetworkPolicy: closing the flat network",id:"networkpolicy-closing-the-flat-network",level:2},{value:"Where this leaves the app",id:"where-this-leaves-the-app",level:2}];function h(e){let n={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"configuration--access-control",children:"Configuration & Access Control"})}),"\n",(0,o.jsx)(a.A,{src:"decks/m8-config-access-control.html",title:"M8 \u2014 Configuration & Access Control"}),"\n",(0,o.jsx)(n.p,{children:"By now Fernwood Goods runs fully on the cluster. A frontend Deployment, a backend Deployment, a\nPostgres StatefulSet, Services wiring them together, and an Envoy front door that lets the outside world in.\nIt works. But two things are still wide open, and both would fail a production review."}),"\n",(0,o.jsx)(n.p,{children:"First, the app's configuration sits in the wrong places. Back in M6, the backend's database host was typed\nstraight into the Deployment manifest as a plain value. The database password sits in plain sight in the\nStatefulSet. To point the same image at a different database, you would edit YAML and redeploy. That is\nconfig welded to the workload, and it is the first thing an auditor flags."}),"\n",(0,o.jsx)(n.p,{children:"Second, the cluster trusts everyone. Any Pod can open a connection to any other Pod. The frontend could\ntalk straight to Postgres. A debug Pod could reach the database, and nothing stops it. And anyone holding a\nkubeconfig (the file that holds your cluster login) can do anything: read every Secret, delete any\nDeployment, in any namespace. A flat, fully-trusting cluster is fine on your laptop. It gets dangerous the\nmoment more than one team shares it."}),"\n",(0,o.jsxs)(n.p,{children:["This lesson closes both gaps. You will pull configuration out of the workload into ",(0,o.jsx)(n.strong,{children:"ConfigMaps"})," and\n",(0,o.jsx)(n.strong,{children:"Secrets"}),". Then you will learn the three checks Kubernetes uses to decide who may do what:\n",(0,o.jsx)(n.strong,{children:"authentication, authorization, and admission control"}),". You will meet the ",(0,o.jsx)(n.strong,{children:"RBAC"})," model that spells out\npermissions, and ",(0,o.jsx)(n.strong,{children:"NetworkPolicy"}),", which finally limits which Pods may talk to which."]}),"\n",(0,o.jsx)(n.h2,{id:"the-analogy-a-secured-research-campus",children:"The analogy: a secured research campus"}),"\n",(0,o.jsx)(n.p,{children:"Imagine a large research campus. Several buildings, hundreds of staff, and some of the work is highly\nsensitive. Nobody memorises how the whole campus runs. Two very different things are going on here, and it\nhelps to keep them apart from the start."}),"\n",(0,o.jsxs)(n.p,{children:["The first is ",(0,o.jsx)(n.strong,{children:"configuration"}),". Every workstation has a printed ",(0,o.jsx)(n.strong,{children:"standing-orders sheet"})," taped beside it:\nwhich server to log into, which printer to use, which project code to bill. The truly sensitive values,\nlike door codes and safe combinations, are not on that sheet. They sit in a ",(0,o.jsx)(n.strong,{children:"sealed envelope"})," in a locked\ndrawer. Here is the important point: the ",(0,o.jsx)(n.em,{children:"worker"})," and the ",(0,o.jsx)(n.em,{children:"instructions"})," are separate. A new hire sits down,\nreads the sheet, and gets to work. Move them to another project and you swap the sheet, not the person."]}),"\n",(0,o.jsxs)(n.p,{children:["The second is ",(0,o.jsx)(n.strong,{children:"access control"}),", and the campus runs it as three checks. A ",(0,o.jsx)(n.strong,{children:"guard at the gate"})," checks\nwho you are against your ID card. That is ",(0,o.jsx)(n.strong,{children:"authentication"}),". Your ",(0,o.jsx)(n.strong,{children:"badge's clearance level"})," then decides\nwhich doors actually open for you. That is ",(0,o.jsx)(n.strong,{children:"authorization"}),". And a ",(0,o.jsx)(n.strong,{children:"mailroom inspection"})," looks at\nanything you try to bring in, and can reject it or stamp a correction on it before it goes further. That is\n",(0,o.jsx)(n.strong,{children:"admission control"}),". Three separate checks, in order: ",(0,o.jsx)(n.em,{children:"who are you"}),", ",(0,o.jsx)(n.em,{children:"what are you allowed to do"}),", and\n",(0,o.jsx)(n.em,{children:"is what you are asking for acceptable"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["Two more campus facts matter. Automated equipment, say a delivery robot or a sensor rig, also needs a\nbadge. It gets a ",(0,o.jsx)(n.strong,{children:"machine credential"}),", not a person's ID. And inside the buildings, not every corridor\nconnects to every room. Sealed doors keep the isolation wing reachable only from the wards that should\nreach it. Keep this whole picture in mind. The rest of the lesson is just the Kubernetes name for each part\nof it."]}),"\n",(0,o.jsx)(n.h2,{id:"moving-configuration-out-configmaps-and-secrets",children:"Moving configuration out: ConfigMaps and Secrets"}),"\n",(0,o.jsx)(n.p,{children:"Back in M6 you wired the backend to Postgres by typing the database's DNS name straight into the\nDeployment:"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-yaml",children:'env:\n  - name: DB_HOST\n    value: "db-0.db.fernwood.svc.cluster.local"\n'})}),"\n",(0,o.jsxs)(n.p,{children:["That worked, and for one value it was fine. But think about what it means. The address of a ",(0,o.jsx)(n.em,{children:"backing\nservice"})," (a thing your app depends on, like the database) is now baked into the ",(0,o.jsx)(n.em,{children:"workload definition"}),". The\nbackend image already reads five settings from its environment: ",(0,o.jsx)(n.code,{children:"DB_HOST"}),", ",(0,o.jsx)(n.code,{children:"DB_PORT"}),", ",(0,o.jsx)(n.code,{children:"DB_NAME"}),", ",(0,o.jsx)(n.code,{children:"DB_USER"}),",\n",(0,o.jsx)(n.code,{children:"DB_PASSWORD"}),". If every one of those is a plain value in the manifest, then the manifest belongs to one\nenvironment only. Staging has a different database host. Production has a different password. You end up\nwith three near-identical manifests that differ only in a few strings, and every difference is a chance to\nship the wrong one."]}),"\n",(0,o.jsxs)(n.p,{children:["The rule underneath this is worth stating plainly. ",(0,o.jsx)(n.strong,{children:"Configuration that changes between environments does\nnot belong in the image, and it does not belong hardcoded in the workload either."})," The image is built\nonce and should run unchanged everywhere. What changes per environment is data the workload reads at\nstartup. Kubernetes gives you two objects to hold that data."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"ConfigMap"})," holds non-secret configuration as key/value pairs. This is the standing-orders sheet: the\ndatabase host, port, name, and user, which are settings you would not mind someone reading. A ",(0,o.jsx)(n.strong,{children:"Secret"}),"\nholds the values you would never print on a sheet, here the database password. It is the sealed envelope."]}),"\n",(0,o.jsxs)(n.p,{children:["Now here is the honest truth about Secrets, and it catches people. ",(0,o.jsx)(n.strong,{children:"A Secret is not encrypted by\ndefault."})," Its values are base64-encoded, which is ",(0,o.jsx)(n.em,{children:"encoding, not encryption"}),". Anyone can decode it in one\ncommand. So what does a Secret actually buy you over a ConfigMap? Two real things. It is a ",(0,o.jsx)(n.strong,{children:"separate object\nwith its own RBAC"}),", so you can let a team read the ConfigMap while denying them the Secret. And the\nplatform handles it more carefully: kept out of most logs, mountable as an in-memory file, and encryptable\nat rest if the cluster turns that on. The separation is the point. Secrets and non-secrets get different\npermissions because they carry different risk."]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  subgraph img [Built once, runs everywhere]\n    I[backend image<br/>reads DB_* from env]\n  end\n  CM[ConfigMap backend-config<br/>DB_HOST, DB_PORT, DB_NAME, DB_USER] --\x3e|envFrom| I\n  S[Secret backend-secret<br/>DB_PASSWORD] --\x3e|envFrom| I"}),"\n",(0,o.jsxs)(n.p,{children:["The workload pulls both in with ",(0,o.jsx)(n.code,{children:"envFrom"}),", which injects ",(0,o.jsx)(n.strong,{children:"every"})," key in the object as an environment\nvariable of the same name. Because the backend already reads ",(0,o.jsx)(n.code,{children:"DB_HOST"}),", ",(0,o.jsx)(n.code,{children:"DB_NAME"})," and the rest from its\nenvironment, the keys line up and nothing in the application code changes. The Deployment's env block that\nused to hold a plain ",(0,o.jsx)(n.code,{children:"DB_HOST"})," value becomes two references:"]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-yaml",children:"envFrom:\n  - configMapRef:\n      name: backend-config\n  - secretRef:\n      name: backend-secret\n"})}),"\n",(0,o.jsxs)(n.p,{children:["That is the whole move. The image is untouched. The behaviour is identical, and the app still reports\n",(0,o.jsx)(n.code,{children:"db: connected"}),". But the configuration now lives in objects you can review, diff, and permission\nseparately from the workload, and the same image will run against any database by swapping the ConfigMap\nand Secret. When you need a single value in one specific place rather than the whole set, ",(0,o.jsx)(n.code,{children:"valueFrom"})," pulls\none key (",(0,o.jsx)(n.code,{children:"configMapKeyRef"})," or ",(0,o.jsx)(n.code,{children:"secretKeyRef"}),") instead of the wholesale ",(0,o.jsx)(n.code,{children:"envFrom"}),". You will use both."]}),"\n",(0,o.jsx)(n.admonition,{title:"Config drift is a real failure mode",type:"note",children:(0,o.jsxs)(n.p,{children:["When a Pod reads config through ",(0,o.jsx)(n.code,{children:"envFrom"}),", it reads it ",(0,o.jsx)(n.strong,{children:"once, at container start"}),". Editing the ConfigMap\nlater does not change a running Pod. You must roll the Deployment for the new values to take effect. That\nis not a bug. It is why a config change is a deploy, not a silent live edit. It also means a Pod that still\nreferences a key that no longer exists will fail to start at all, which is one of the drills in this\nmodule's deep dive."]})}),"\n",(0,o.jsx)(n.h2,{id:"three-gates-authentication-authorization-admission-control",children:"Three gates: authentication, authorization, admission control"}),"\n",(0,o.jsxs)(n.p,{children:["Now to access control. Every request to the Kubernetes API server (every ",(0,o.jsx)(n.code,{children:"kubectl"}),' command, and every Pod\nusing its token) passes through three stages, in a fixed order, before it is allowed to change anything.\nThese are the guard, the badge reader, and the mailroom from the analogy, and keeping them apart is what\nlets you debug a "permission" problem correctly.']}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  R[Request<br/>kubectl / Pod token] --\x3e A{AuthN<br/>who are you?}\n  A --\x3e|verified identity| Z{AuthZ<br/>are you allowed?}\n  A --\x3e|unknown| X1[401 Unauthorized]\n  Z --\x3e|permitted| AD{Admission<br/>is it acceptable?}\n  Z --\x3e|denied| X2[403 Forbidden]\n  AD --\x3e|accepted / mutated| DB[(persisted to etcd)]\n  AD --\x3e|rejected| X3[request rejected]"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Authentication (authN)"})," answers ",(0,o.jsx)(n.em,{children:"who are you?"}),' The API server checks the caller\'s identity from the\ncredential they present: a client certificate, a bearer token, or, for a Pod, its Service Account token.\nKubernetes has no built-in "user" object for humans. It trusts an outside identity source and reads the\nidentity off the credential. If the credential is invalid, the request stops here with ',(0,o.jsx)(n.code,{children:"401"}),". Notice what\nauthN does ",(0,o.jsx)(n.strong,{children:"not"})," do: it does not decide what you can do. The guard confirms your ID. It does not open any\ndoors."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Authorization (authZ)"})," answers ",(0,o.jsx)(n.em,{children:"are you allowed to do this?"})," Now that the API server knows who you are,\nit checks whether that identity may perform this specific action (the verb) on this specific resource in\nthis specific namespace: ",(0,o.jsx)(n.code,{children:"delete pods in fernwood"}),", or ",(0,o.jsx)(n.code,{children:"get secrets in kube-system"}),". In this course, and in\nalmost every real cluster, the system doing that checking is ",(0,o.jsx)(n.strong,{children:"RBAC"}),". If no rule permits the action, the\nrequest stops here with ",(0,o.jsx)(n.code,{children:"403 Forbidden"}),". This is the badge reader: identity already known, now the question\nis clearance."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Admission control"})," answers ",(0,o.jsx)(n.em,{children:"is what you are asking for acceptable, and should it be adjusted?"})," Even a\nfully-authorized request can be rejected or changed at this last gate by admission controllers, the\nmailroom inspection. ",(0,o.jsx)(n.strong,{children:"Mutating"})," admission can change the request (inject a sidecar, set a default,\nadd a label). ",(0,o.jsx)(n.strong,{children:"Validating"}),' admission can reject it against a policy ("every Pod must set resource limits",\n"no privileged containers"). This is how a platform team enforces standards that RBAC cannot express. RBAC\nsays ',(0,o.jsx)(n.em,{children:"who"})," may act. Admission says ",(0,o.jsx)(n.em,{children:"what shape"})," the result must have. Only after all three gates does the\nchange land in etcd."]}),"\n",(0,o.jsxs)(n.p,{children:['Here is why you keep these apart. When something is "denied," the stage tells you the cause. A ',(0,o.jsx)(n.code,{children:"401"})," is an\nidentity problem (bad or missing credential). A ",(0,o.jsx)(n.code,{children:"403"})," is an RBAC problem (identity fine, permission\nmissing). A rejection with a policy message is admission (permission fine, the object breaks a rule).\nThree different fixes."]}),"\n",(0,o.jsx)(n.h2,{id:"service-accounts-identity-for-pods",children:"Service Accounts: identity for Pods"}),"\n",(0,o.jsxs)(n.p,{children:["Humans authenticate with certificates or tokens from an outside identity provider. But a Pod also makes\nAPI calls: a controller reconciling objects, the ingress controller reading Ingress rules, your own app\nlisting Pods. What identity does ",(0,o.jsx)(n.em,{children:"it"})," use? That is the machine credential from the analogy: a ",(0,o.jsx)(n.strong,{children:"Service\nAccount"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["A Service Account is an identity for workloads, native to Kubernetes and tied to one namespace. Every Pod\nruns as one. If you do not name it, the Pod uses the ",(0,o.jsx)(n.code,{children:"default"})," Service Account in its namespace. Kubernetes\nmounts a token for that Service Account into the Pod, and when the Pod calls the API server, that token is\nits credential. The API server authenticates the call as ",(0,o.jsx)(n.code,{children:"system:serviceaccount:<namespace>:<name>"}),". This\nis the same as a person's ID badge, except it is issued to a process, not a person, and it is confined to\none namespace."]}),"\n",(0,o.jsxs)(n.p,{children:["The security lesson here is the same as least privilege everywhere. The ",(0,o.jsx)(n.code,{children:"default"})," Service Account should be\nable to do almost nothing, and any Pod that genuinely needs API access should run as a ",(0,o.jsx)(n.strong,{children:"purpose-made\nService Account"})," granted exactly the permissions it needs, and no more. In the lab you create a Service\nAccount that can only read Pods in ",(0,o.jsx)(n.code,{children:"fernwood"}),", and prove it can do that and nothing else."]}),"\n",(0,o.jsx)(n.h2,{id:"rbac-roles-clusterroles-and-bindings",children:"RBAC: Roles, ClusterRoles, and bindings"}),"\n",(0,o.jsxs)(n.p,{children:['Authorization needs a language for "who may do what, where." That language is ',(0,o.jsx)(n.strong,{children:"Role-Based Access Control"}),",\nand it is built from just two types of object: ones that ",(0,o.jsx)(n.strong,{children:"define a set of permissions"}),", and ones that\n",(0,o.jsx)(n.strong,{children:"grant that set to a subject"}),". A subject is a user, a group, or a Service Account."]}),"\n",(0,o.jsx)(n.p,{children:"The permission-defining objects come in a namespaced form and a cluster-wide form, and this split maps\nstraight onto the namespaces you learned in M4:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"Role"}),' is namespaced. Its rules apply only inside one namespace. "Read Pods in ',(0,o.jsx)(n.code,{children:"fernwood"}),'" is a Role.\nThis is the wing-specific badge. It opens doors in one wing only.']}),"\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"ClusterRole"})," is cluster-scoped. The same type of rules, but they apply cluster-wide, and a\nClusterRole can also grant access to cluster-scoped resources (Nodes, PersistentVolumes, and namespaces\nthemselves) that a Role cannot even name. This is the facility-wide badge."]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["A Role or ClusterRole on its own grants nothing. It is a definition sitting on a shelf. The ",(0,o.jsx)(n.strong,{children:"binding"}),"\nattaches it to a subject:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"RoleBinding"})," grants a Role (or a ClusterRole) ",(0,o.jsx)(n.strong,{children:"within one namespace"}),'. It says "this subject has\nthese permissions, here."']}),"\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"ClusterRoleBinding"})," grants a ClusterRole ",(0,o.jsx)(n.strong,{children:"across the whole cluster"}),"."]}),"\n"]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart TD\n  subgraph def [Define permissions]\n    RO[Role<br/>namespaced rules]\n    CR[ClusterRole<br/>cluster-wide rules]\n  end\n  subgraph grant [Grant to a subject]\n    RB[RoleBinding<br/>in one namespace]\n    CRB[ClusterRoleBinding<br/>whole cluster]\n  end\n  SA[ServiceAccount<br/>pod-reader] --\x3e RB\n  RO --\x3e RB\n  CR -.reuse cluster-wide rules<br/>but scope to one ns.-> RB\n  CR --\x3e CRB"}),"\n",(0,o.jsxs)(n.p,{children:["One combination is worth calling out because it is genuinely useful: a ",(0,o.jsx)(n.strong,{children:"RoleBinding can reference a\nClusterRole"}),'. That lets the platform team define a reusable permission set once as a ClusterRole (say,\n"read-only across common resources") and then grant it ',(0,o.jsx)(n.em,{children:"namespace by namespace"})," with RoleBindings. The\npermission is scoped to wherever the binding lives, not cluster-wide. Define once, grant narrowly."]}),"\n",(0,o.jsxs)(n.p,{children:["The discipline that makes RBAC safe is ",(0,o.jsx)(n.strong,{children:"least privilege"}),". Grant the narrowest actions (",(0,o.jsx)(n.code,{children:"get"}),", ",(0,o.jsx)(n.code,{children:"list"}),") on\nthe fewest resources (",(0,o.jsx)(n.code,{children:"pods"}),") in the smallest scope (one namespace) that does the job. It is far easier to\nadd a permission when something genuinely needs it than to discover, during an incident, that a\nService Account could delete production because someone bound ",(0,o.jsx)(n.code,{children:"cluster-admin"})," to be safe. In the lab you\nwill feel this directly: a Service Account that can list Pods but gets a hard ",(0,o.jsx)(n.code,{children:"Forbidden"})," the moment it\ntries to delete one."]}),"\n",(0,o.jsx)(n.h2,{id:"networkpolicy-closing-the-flat-network",children:"NetworkPolicy: closing the flat network"}),"\n",(0,o.jsxs)(n.p,{children:["The last gap is the network itself. Go all the way back to M1. Docker gave every container on a bridge a\nflat network where everyone could reach everyone. That default carried into Kubernetes. By default,\n",(0,o.jsx)(n.strong,{children:"every Pod can open a connection to every other Pod"}),", across namespaces, with nothing in the way. The\nfrontend could connect straight to Postgres. A debug Pod someone left running could reach the database.\nNothing is stopping it, because nothing has been told to."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"NetworkPolicy"})," changes the default from open to closed, then reopens only the paths you name. It is\nthe sealed internal doors of the campus. The isolation wing is reachable only from the wards that should\nreach it, and every other corridor to it is walled off."]}),"\n",(0,o.jsxs)(n.p,{children:["Two facts decide whether a NetworkPolicy does anything at all. First, policies are ",(0,o.jsx)(n.strong,{children:"additive, and\nthey default to deny once they select a Pod"}),". The moment ",(0,o.jsx)(n.em,{children:"any"})," policy selects a Pod for a direction\n(ingress, which is traffic coming in, or egress, which is traffic going out), that Pod denies all traffic\nin that direction ",(0,o.jsx)(n.em,{children:"except"})," what some policy explicitly allows. A Pod that no policy selects stays wide\nopen. So the standard pattern is a ",(0,o.jsx)(n.strong,{children:"default-deny"})," policy that selects every Pod and permits nothing,\nfollowed by narrow allow-policies that add back exactly the paths you want."]}),"\n",(0,o.jsxs)(n.p,{children:["Second, and this is why the course's cluster is built the way it is, ",(0,o.jsx)(n.strong,{children:"NetworkPolicy is enforced by the\nCNI plugin, not by Kubernetes core."})," (The CNI is the network plugin that wires up Pod networking.) The\nAPI server will happily accept a NetworkPolicy object under a CNI that ignores it, and you will believe you\nare protected while every packet still flows. This course's KIND cluster runs ",(0,o.jsx)(n.strong,{children:"Calico"})," precisely because\nthe default kindnet CNI does ",(0,o.jsx)(n.strong,{children:"not"})," enforce NetworkPolicy. That decision, made back in M3, is what makes\nthis lesson real instead of theatre."]}),"\n",(0,o.jsx)(n.p,{children:"For Fernwood the intended shape is a simple chain plus the ingress exception:"}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  ENV[Envoy / projectcontour] --\x3e|:3000| FE[frontend Pods]\n  ENV --\x3e|:8080| BE[backend Pods]\n  FE --\x3e|:8080| BE\n  BE --\x3e|:5432| DB[(db Pods)]\n  X[any other Pod] -.blocked.-> BE\n  X -.blocked.-> DB"}),"\n",(0,o.jsxs)(n.p,{children:["Default-deny everything, then allow: the frontend reachable from Envoy on 3000; the backend reachable from\nthe frontend ",(0,o.jsx)(n.em,{children:"and"})," Envoy on 8080; the database reachable from the backend and nothing else on 5432. Every\nother path is dropped: a stray Pod dialling the backend, or anyone at all dialling Postgres."]}),"\n",(0,o.jsxs)(n.p,{children:["That ingress exception for Envoy is not optional. The whole front door you built in M7 depends on Envoy\nPods in the ",(0,o.jsx)(n.code,{children:"projectcontour"})," namespace reaching the frontend and backend. A default-deny that forgets to\nallow ",(0,o.jsx)(n.code,{children:"projectcontour"})," would silently break Ingress routing. The app would look up and pass its health\nchecks while every external request returned a 503. This is the most common way a well-meaning\nNetworkPolicy takes down a working app, and the lab makes you prove Ingress still routes after the policy is\napplied."]}),"\n",(0,o.jsx)(n.h2,{id:"where-this-leaves-the-app",children:"Where this leaves the app"}),"\n",(0,o.jsx)(n.p,{children:"At the end of this module's lab, Fernwood is hardened without a single change to its application code. Its\nconfiguration lives in a ConfigMap and a Secret you can permission independently. A scoped Service Account\nproves the RBAC boundary works. And a default-deny NetworkPolicy, with named exceptions, means the only Pod\nthat can reach Postgres is the backend, while the M7 front door keeps serving traffic. That is the shape\nof a service that could pass a review."}),"\n",(0,o.jsx)(n.p,{children:"The next lesson steps back from the mechanics. You have spent eight modules building one small system into\na set of independent, separately-deployed, network-isolated services. Lesson 2 names what you actually\nbuilt, which is the microservices patterns hiding in plain sight across the whole course, and it is honest\nabout what that architecture costs."})]})}function u(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},7684(e,n,t){t.d(n,{A:()=>i});var s=t(4848);t(6540);var o=t(6497);function i({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,s.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var s=t(6540);let o={},i=s.createContext(o);function a(e){let n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);